        uint256 t2 = _buy(r, usdc, BOB, 50);
        _eq(r.accountedQuoteBalance(), 100e6, "credited");
        _eq(usdc.balanceOf(address(r)), 99e6, "received");
        vm.warp(uint256(r.endTime()) + 2 days);
