    }

    function test_noReturnToken_supportedBySafeERC20() public {
        NoReturnUSD q = new NoReturnUSD();
        RaffleFactory f = new RaffleFactory(address(q), address(vrf), TREASURY);
        StdNFT nft = new StdNFT();
